#include "buffer_pool.h"

uint32_t buf_pool_get_slot_offset(uint32_t slot_idx) {
  return slot_idx * PAGE_SIZE;
}

uint32_t buf_pool_read_slot_to_page(uint32_t slot_to_page_offset, uint32_t slot_idx) {
  return load_u32((const void *)(uintptr_t)(slot_to_page_offset + slot_idx * 4));
}

void buf_pool_write_slot_to_page(uint32_t slot_to_page_offset, uint32_t slot_idx, uint32_t page_id) {
  store_u32((void *)(uintptr_t)(slot_to_page_offset + slot_idx * 4), page_id);
}

int32_t buf_pool_get_resident_slot(uint32_t page_to_slot_offset, uint32_t page_to_slot_buckets, uint32_t page_id) {
  return page_table_get(page_to_slot_offset, page_to_slot_buckets, page_id);
}

int32_t buf_pool_assign_slot(uint32_t slot_to_page_offset, uint32_t page_to_slot_offset, uint32_t page_to_slot_buckets, uint32_t slot_idx, uint32_t page_id) {
  if (!(page_id > 0)) return -1;
  uint32_t old_page = buf_pool_read_slot_to_page(slot_to_page_offset, slot_idx);
  if (old_page > 0 && old_page != page_id) {
    page_table_delete(page_to_slot_offset, page_to_slot_buckets, old_page);
  }
  buf_pool_write_slot_to_page(slot_to_page_offset, slot_idx, page_id);
  page_table_set(page_to_slot_offset, page_to_slot_buckets, page_id, slot_idx);
  return 0;
}

int32_t buf_pool_unassign_slot(uint32_t slot_to_page_offset, uint32_t page_to_slot_offset, uint32_t page_to_slot_buckets, uint32_t slot_idx) {
  uint32_t old_page = buf_pool_read_slot_to_page(slot_to_page_offset, slot_idx);
  if (old_page > 0) {
    page_table_delete(page_to_slot_offset, page_to_slot_buckets, old_page);
    buf_pool_write_slot_to_page(slot_to_page_offset, slot_idx, 0);
    return 1;
  }
  return 0;
}

void buf_pool_mark_dirty(uint32_t dirty_mask_offset, uint32_t slot_idx) {
  set_bit((uint8_t *)(uintptr_t)(dirty_mask_offset), slot_idx);
}

void buf_pool_clear_dirty(uint32_t dirty_mask_offset, uint32_t slot_idx) {
  clear_bit((uint8_t *)(uintptr_t)(dirty_mask_offset), slot_idx);
}

int32_t buf_pool_is_dirty(uint32_t dirty_mask_offset, uint32_t slot_idx) {
  return get_bit((const uint8_t *)(uintptr_t)(dirty_mask_offset), slot_idx) == 1;
}
